define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_27.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e152336","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_26.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e152440","topics":[]},{"title":"Applying LOTO - MDP","shortdesc":"<p class=\"shortdesc\"><span class=\"ph uicontrol\">Note: <\/span>Prior to applying LOTO to the system do the Disk Wipe procedure, which can be found on the documentation library. Search on document 5500610-1. Apply LOTO to the MDP or the facility PDU before removing power to these items. Facility-level LOTO must be done by an electrician.<\/p>","href":"t_Applying-LOTO-MDP-Premier_7.html","attributes":{"data-id":"id_2001934"},"menu":{"hasChildren":false},"tocID":"id_2001934-d46e152544","topics":[]},{"title":"Removing the Facility Plumbing Unit (FPU) sensor","shortdesc":"<p class=\"shortdesc\">Removes the Facility Plumbing Unit (FPU) sensor from the FPU.<\/p>","href":"t_RemovingTheFacilityPlumbingUnitFPUSensor.html","attributes":{"data-id":"id_2014591"},"menu":{"hasChildren":true},"tocID":"id_2014591-d46e152650","next":"id_2014591-d46e152650"},{"title":"Installing the Facility Plumbing Unit (FPU) sensor","shortdesc":"<p class=\"shortdesc\">Installs the Facility Plumbing Unit (FPU) sensor in the FPU.<\/p>","href":"t_InstallingTheFacilityPlumbingUnitFPUSensor.html","attributes":{"data-id":"id_2014592"},"menu":{"hasChildren":false},"tocID":"id_2014592-d46e152859","topics":[]},{"title":"Removing LOTO - MDP","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the MDP or the facility PDU before restoring power to these items. Facility-level LOTO must be done by an electrician.<\/p>","href":"t_Removing-LOTO-MDP-Premier_6.html","attributes":{"data-id":"id_2001935"},"menu":{"hasChildren":false},"tocID":"id_2001935-d46e152963","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_26.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e153072","topics":[]},{"title":"Adjusting facility water flow rate","shortdesc":"<p class=\"shortdesc\">Use this procedure to check and adjust the current facility water flow rate.<\/p>","href":"t_AdjustingFacilityWaterFlowRate_2.html","attributes":{"data-id":"id_2004393"},"menu":{"hasChildren":false},"tocID":"id_2004393-d46e153176","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_45.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e153280","topics":[]}]});